export type Post = {
  id: string;
  title: string;
  content: string;
};

// Simulate a database
let posts: Post[] = [
  { id: '1', title: 'First Post', content: 'This is the first post' },
];

export async function getPostsDB(): Promise<Post[]> {
  // Simulate network delay
  await new Promise((resolve) => setTimeout(resolve, 100));
  return posts;
}

export async function addPostDB(post: Omit<Post, 'id'>): Promise<Post> {
  const newPost = { ...post, id: Math.random().toString(36).slice(2) };
  posts.push(newPost);
  return newPost;
}

import { unstable_cache } from 'next/cache';
import { getPostsDB } from './db';

export const getPosts = unstable_cache(
  async () => {
    return getPostsDB();
  },
  ['posts'], // cache key part (not strictly the tag, but acts as key)
  {
    tags: ['posts'], // The important part for revalidation
  }
);

'use server';

import { revalidateTag } from 'next/cache';
import { addPostDB } from '@/lib/db';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  await addPostDB({ title, content });

  revalidateTag('posts');
}

import { getPosts } from '@/lib/posts';
import { createPost } from './actions';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main>
      <h1>Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>{post.content}</p>
          </li>
        ))}
      </ul>

      <hr />

      <form action={createPost}>
        <div>
          <label htmlFor="title">Title: </label>
          <input type="text" id="title" name="title" required className="border p-1" />
        </div>
        <div>
          <label htmlFor="content">Content: </label>
          <textarea id="content" name="content" required className="border p-1" />
        </div>
        <button type="submit" className="bg-blue-500 text-white p-2 rounded">Create Post</button>
      </form>
    </main>
  );
}

